import (
	"bytes"
	"crypto/rand"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
)

func main() {
	body, err := os.ReadFile("payout.json")
	if err != nil {
		panic(err)
	}
	key := make([]byte, 16)
	rand.Read(key)
	req, _ := http.NewRequest("POST", os.Getenv("DEKERNAI_BASE_URL")+"/v1/payment_intents", bytes.NewReader(body))
	req.Header.Set("Authorization", "Bearer "+os.Getenv("DEKERNAI_API_KEY"))
	req.Header.Set("Idempotency-Key", fmt.Sprintf("%x", key))
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	var payment map[string]any
	json.NewDecoder(resp.Body).Decode(&payment)
	if resp.StatusCode >= 300 {
		panic(fmt.Sprint(resp.StatusCode, payment))
	}
	fmt.Println(payment["id"], payment["status"])
}

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Path;
import java.util.UUID;

public class CreatePayout {
    static final HttpClient HTTP = HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).build();

    public static void main(String[] args) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(System.getenv("DEKERNAI_BASE_URL") + "/v1/payment_intents"))
                .header("Authorization", "Bearer " + System.getenv("DEKERNAI_API_KEY"))
                .header("Idempotency-Key", UUID.randomUUID().toString())
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofFile(Path.of("payout.json")))
                .build();
        HttpResponse<String> response = HTTP.send(request, HttpResponse.BodyHandlers.ofString());
        if (response.statusCode() >= 300) throw new RuntimeException(response.statusCode() + ": " + response.body());
        System.out.println(response.body()); // the payment intent, as JSON
    }
}

